SELECT CASE WHEN sp.prescription_expires_at IS NULL OR sp.prescription_expires_at <= now() THEN 'expired: regenerates as before' WHEN sp.prescription->>'phaseAction' IN ('stay', 'rest_day_recommended', 'session_swap_recommended') THEN 'promote in place' WHEN sp.prescription->>'phaseAction' = 'deload_recommended' AND (sp.prescription->>'deload')::boolean THEN 'one-day deload: promote or end at midnight' WHEN sp.prescription->>'phaseAction' = 'transition_recommended' AND sp.prescription ? 'typeOnlyMove' THEN 'waiting move: stays pending' WHEN sp.prescription->>'phaseAction' = 'transition_recommended' THEN 'move: planned again (1 model call)' ELSE 'left as is' END AS adoption, sp.prescription->>'phaseAction' AS phase_action, count(*) AS plans FROM claude_ro.session_periodization sp JOIN claude_ro.program_sessions ps ON ps.id = sp.program_session_id AND ps.deleted_at IS NULL JOIN claude_ro.programs p ON p.id = ps.program_id WHERE p.is_active AND p.phase_mode = 'ai_dynamic' AND sp.prescription_status = 'pending' AND sp.prescription IS NOT NULL GROUP BY 1, 2 ORDER BY 1, 2
